inline QString NasaqLanguage(){if(qApp && qApp->property("nasaqLiveLanguage").isValid())return qApp->property("nasaqLiveLanguage").toString();static const QString chosen=[](){auto v=qEnvironmentVariable("NASAQ_TEST_LANGUAGE");if(v.isEmpty())v=QSettings(QStringLiteral("NASAQ"),QStringLiteral("Preferences")).value(QStringLiteral("language"),QStringLiteral("system")).toString();if(v==QStringLiteral("system"))v=QLocale::system().name();return v.startsWith(QStringLiteral("ar"))?QStringLiteral("ar"):QStringLiteral("en");}();return chosen;}
