inline QString NText(const QString&s){
 if(s.contains(QStringLiteral(": "))){const auto code=s.section(u':',0,0);if(QStringList{QStringLiteral("play_started"),QStringLiteral("play_stopped"),QStringLiteral("audio_error"),QStringLiteral("tts_error"),QStringLiteral("prayer_reminder"),QStringLiteral("paging"),QStringLiteral("operator")}.contains(code))return NText(code);}
 const bool ar=NasaqLanguage()==QStringLiteral("ar");const auto&m=NasaqCatalog();auto it=m.constFind(s);if(it!=m.cend())return ar?it.value().second:it.value().first;
 if(s.startsWith(QStringLiteral("مفعّل / Active · devices: "))){const auto match=QRegularExpression(QStringLiteral("^مفعّل / Active · devices: (.+) · offline until: (.+)$")).match(s);if(match.hasMatch())return (ar?QStringLiteral("مفعّل · عدد الأجهزة: %1 · السماح دون إنترنت حتى: %2"):QStringLiteral("Active · devices: %1 · offline until: %2")).arg(match.captured(1),match.captured(2));}
 for(auto i=m.cbegin();i!=m.cend();++i)if(i.key().contains(QStringLiteral(" / "))&&s.startsWith(i.key())&&!i.key().contains(u'%'))return (ar?i.value().second:i.value().first)+s.mid(i.key().size());
 return s;
}

class NasaqTranslator final:public QTranslator{public:using QTranslator::QTranslator;bool isEmpty()const override{return false;}QString translate(const char*,const char*s,const char*,int)const override{auto key=QString::fromUtf8(s);if(NasaqCatalog().contains(key))return NText(key);if(key.contains(u'&')){auto plain=key;plain.remove(u'&');if(NasaqCatalog().contains(plain))return NText(plain);}return {};}};
